// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= 100 ether);

        address caller = address(0x1337);
        vm.deal(caller, amount);

        vm.warp(1);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: amount}("");

        if (ok) {
            assertTrue(address(c).balance % 10 ether == 0);
        }
    }
}
